import React, { useState } from 'react'
import { Link, useLocation } from 'react-router-dom'
import { FaSun, FaMoon, FaBars, FaTimes } from 'react-icons/fa'
import { motion, AnimatePresence } from 'framer-motion'

const navItems = [
  { path: '/', label: 'Home' },
  { path: '/skills', label: 'Skills' },
  { path: '/projects', label: 'Projects' },
  { path: '/experience', label: 'Experience' },
  { path: '/resume', label: 'Resume' },
  { path: '/contact', label: 'Contact' },
]

const Navbar = ({ darkMode, toggleDarkMode }) => {
  const [isOpen, setIsOpen] = useState(false)
  const location = useLocation()

  return (
    <nav
      className={`fixed w-full top-0 z-50 flex items-center justify-between px-6 md:px-20 py-4 shadow-md transition-colors duration-300 ${
        darkMode ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'
      }`}
    >
      {/* LOGO */}
      <Link
        to="/"
        className="text-3xl font-extrabold tracking-tight bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500 bg-clip-text text-transparent hover:opacity-90 transition duration-300 whitespace-nowrap font-poppins"
      >
        Harsh.
      </Link>

      {/* DESKTOP NAV LINKS */}
      <ul className="hidden sm:flex gap-6 text-sm font-semibold">
        {navItems.map(({ path, label }) => {
          const isActive = location.pathname === path
          return (
            <li key={path}>
              <Link
                to={path}
                className={`relative font-poppins transition-colors duration-200 hover:text-blue-500 ${
                  isActive ? 'text-blue-500' : ''
                }`}
              >
                {label}
                {isActive && (
                  <motion.span
                    layoutId="underline"
                    className="absolute -bottom-1 left-0 right-0 h-0.5 bg-blue-500 rounded-full"
                  />
                )}
              </Link>
            </li>
          )
        })}
      </ul>

      {/* RIGHT SIDE */}
      <div className="flex items-center gap-3">
        <button
          onClick={toggleDarkMode}
          className={`text-xl p-2 rounded-full transition ${
            darkMode ? 'hover:bg-gray-700' : 'hover:bg-gray-100'
          }`}
          aria-label="Toggle dark mode"
        >
          {darkMode ? (
            <FaSun className="text-yellow-400" />
          ) : (
            <FaMoon className="text-blue-500" />
          )}
        </button>

        <button
          onClick={() => setIsOpen(!isOpen)}
          className="text-2xl sm:hidden"
          aria-label="Toggle mobile menu"
        >
          {isOpen ? <FaTimes /> : <FaBars />}
        </button>
      </div>

      {/* MOBILE NAV */}
      <AnimatePresence>
        {isOpen && (
          <motion.ul
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className={`absolute top-16 right-6 w-48 rounded-xl shadow-xl p-4 space-y-3 sm:hidden z-40 ${
              darkMode ? 'bg-gray-800 text-white' : 'bg-white text-gray-900'
            }`}
          >
            {navItems.map(({ path, label }) => {
              const isActive = location.pathname === path
              return (
                <li key={path}>
                  <Link
                    to={path}
                    onClick={() => setIsOpen(false)}
                    className={`block text-sm font-semibold font-poppins transition-colors duration-200 hover:text-blue-500 ${
                      isActive ? 'text-blue-500' : ''
                    }`}
                  >
                    {label}
                  </Link>
                </li>
              )
            })}
          </motion.ul>
        )}
      </AnimatePresence>
    </nav>
  )
}

export default Navbar
